import { Command } from 'commander';

export function createProgram(): Command {
  const program = new Command();

  program
    .name('devguard')
    .description('Developer productivity CLI for preventive code-review analysis')
    .version('1.0.0');

  const analyze = program
    .command('analyze')
    .description('Analyze repositories for risks and contract mismatches');

  analyze
    .command('local')
    .description('Analyze local Git repositories')
    .requiredOption('--config <path>', 'Path to .devguard.yml configuration file')
    .option('--requirements <path>', 'Path to requirements file')
    .option('--output <directory>', 'Output directory for reports')
    .option('--verbose', 'Enable verbose output')
    .option('--fail-below <score>', 'Exit with non-zero code if score is below threshold', parseInt)
    .action((_options: unknown) => {
      console.log('DevGuard analyze local — not yet implemented.');
    });

  return program;
}

#!/usr/bin/env node

import { createProgram } from './program.js';

const program = createProgram();
program.parse(process.argv);

import { describe, it, expect } from 'vitest';
import { createProgram } from './program.js';

describe('DevGuard CLI', () => {
  it('should create a program with the correct name', () => {
    const program = createProgram();
    expect(program.name()).toBe('devguard');
  });

  it('should have an analyze command', () => {
    const program = createProgram();
    const analyze = program.commands.find((cmd) => cmd.name() === 'analyze');
    expect(analyze).toBeDefined();
  });

  it('should have a local subcommand under analyze', () => {
    const program = createProgram();
    const analyze = program.commands.find((cmd) => cmd.name() === 'analyze');
    const local = analyze?.commands.find((cmd) => cmd.name() === 'local');
    expect(local).toBeDefined();
  });

  it('should require --config option for analyze local', () => {
    const program = createProgram();
    const analyze = program.commands.find((cmd) => cmd.name() === 'analyze');
    const local = analyze?.commands.find((cmd) => cmd.name() === 'local');
    const configOption = local?.options.find((opt) => opt.long === '--config');
    expect(configOption).toBeDefined();
    expect(configOption?.required).toBe(true);
  });
});

